1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"strconv"
10		"strings"
11		"time"
12		"unicode/utf8"
13	
14		"github.com/gin-gonic/gin"
15	
16		"github.com/xjeey8iust/sen-audit-ledger/internal/store"
17	)
18	
19	// maxEventBodyBytes bounds one audit event payload.
20	const maxEventBodyBytes = 1 << 20
21	
22	// eventResponse is the 201 body for a persisted record.
23	type eventResponse struct {
24		Account    string `json:"account"`
25		Operation  string `json:"operation"`
26		Resource   string `json:"resource"`
27		Result     string `json:"result"`
28		OccurredAt string `json:"occurred_at"`
29		Seq        int64  `json:"seq"`
30		PrevHash   string `json:"prev_hash"`
31		Hash       string `json:"hash"`
32	}
33	
34	// postEvent appends one audit record to the ledger.
35	func postEvent(st *store.Store) gin.HandlerFunc {
36		return func(c *gin.Context) {
37			input, ok := parseEventInput(c)
38			if !ok {
39				return
40			}
41			event, err := st.Append(input)
42			if err != nil {
43				switch {
44				case errors.Is(err, store.ErrSeqConflict):
45					writeError(c, http.StatusConflict, "audit_seq_conflict", "seq already exists in the ledger")
46				case errors.Is(err, store.ErrSeqGap):
47					writeError(c, http.StatusBadRequest, "invalid_audit_input", "seq must be the next sequence number")
48				default:
49					writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "storage is not available")
50				}
51				return
52			}
53			c.JSON(http.StatusCreated, eventResponse{
54				Account:    event.Account,
55				Operation:  event.Operation,
56				Resource:   event.Resource,
57				Result:     event.Result,
58				OccurredAt: event.OccurredAt,
59				Seq:        event.Seq,
60				PrevHash:   event.PrevHash,
61				Hash:       event.Hash,
62			})
63		}
64	}
65	
66	// parseEventInput validates the request body against the audit contract. On
67	// any violation it writes the invalid_audit_input error and reports false.
68	func parseEventInput(c *gin.Context) (store.EventInput, bool) {
69		var input store.EventInput
70		invalid := func() (store.EventInput, bool) {
71			writeError(c, http.StatusBadRequest, "invalid_audit_input", "request body is not a valid audit event")
72			return store.EventInput{}, false
73		}
74	
75		body, err := io.ReadAll(io.LimitReader(c.Request.Body, maxEventBodyBytes+1))
76		if err != nil || len(body) > maxEventBodyBytes {
77			return invalid()
78		}
79	
80		// The JSON decoder silently rewrites invalid UTF-8 bytes and unpaired
81		// surrogate escapes to U+FFFD; the ledger must only store text that
82		// decodes losslessly, so reject both before decoding.
83		if !utf8.Valid(body) || hasUnpairedSurrogateEscape(body) {
84			return invalid()
85		}
86	
87		var raw map[string]json.RawMessage
88		decoder := json.NewDecoder(bytes.NewReader(body))
89		if err := decoder.Decode(&raw); err != nil || raw == nil {
90			return invalid()
91		}
92		var extra struct{}
93		if err := decoder.Decode(&extra); err != io.EOF {
94			return invalid()
95		}
96	
97		for key := range raw {
98			switch key {
99			case "account", "operation", "resource", "result", "occurred_at", "seq":
100			default:
101				// hash, prev_hash and any unknown field are forbidden.
102				return invalid()
103			}
104		}
105	
106		var ok bool
107		if input.Account, ok = requiredString(raw, "account"); !ok || strings.TrimSpace(input.Account) == "" {
108			return invalid()
109		}
110		if input.Operation, ok = requiredString(raw, "operation"); !ok || strings.TrimSpace(input.Operation) == "" {
111			return invalid()
112		}
113		if input.Resource, ok = requiredString(raw, "resource"); !ok || strings.TrimSpace(input.Resource) == "" {
114			return invalid()
115		}
116		if input.Result, ok = requiredString(raw, "result"); !ok || strings.TrimSpace(input.Result) == "" {
117			return invalid()
118		}
119		occurredAt, ok := requiredString(raw, "occurred_at")
120		if !ok {
121			return invalid()
122		}
123		if input.OccurredAt, ok = normalizeOccurredAt(occurredAt); !ok {
124			return invalid()
125		}
126	
127		if rawSeq, present := raw["seq"]; present {
128			literal := string(rawSeq)
129			if !isUintLiteral(literal) {
130				return invalid()
131			}
132			seq, err := strconv.ParseInt(literal, 10, 64)
133			if err != nil || seq <= 0 {
134				return invalid()
135			}
136			input.Seq = &seq
137		}
138		return input, true
139	}
140	
141	// hasUnpairedSurrogateEscape scans the raw JSON document for \uXXXX escapes
142	// inside string literals and reports whether any of them encodes a surrogate
143	// that is not one half of an adjacent, correctly ordered pair. A high
144	// surrogate must be followed immediately by a low-surrogate escape inside the
145	// same string; a low surrogate on its own (or a reversed pair) is rejected.
146	// Escaped backslashes are consumed first, so text like "\\uD83D" is read as
147	// plain characters, not as a Unicode escape. Anything the scan cannot parse
148	// is left for the JSON decoder to reject.
149	func hasUnpairedSurrogateEscape(body []byte) bool {
150		inString := false
151		for i := 0; i < len(body); i++ {
152			c := body[i]
153			if !inString {
154				if c == '"' {
155					inString = true
156				}
157				continue
158			}
159			switch c {
160			case '"':
161				inString = false
162			case '\\':
163				if i+1 >= len(body) || body[i+1] != 'u' {
164					// Any other escape (including \\) consumes one byte.
165					i++
166					continue
167				}
168				if i+6 > len(body) {
169					return false // truncated escape: malformed JSON
170				}
171				v, ok := parseHex4(body[i+2 : i+6])
172				if !ok {
173					return false // not hex: the decoder rejects it
174				}
175				switch {
176				case v >= 0xD800 && v <= 0xDBFF:
177					// A high surrogate is only valid as the first half of a
178					// pair immediately followed by a low-surrogate escape.
179					if i+12 <= len(body) && body[i+6] == '\\' && body[i+7] == 'u' {
180						if low, ok := parseHex4(body[i+8 : i+12]); ok && low >= 0xDC00 && low <= 0xDFFF {
181							i += 11
182							continue
183						}
184					}
185					return true
186				case v >= 0xDC00 && v <= 0xDFFF:
187					// A low surrogate without a preceding high surrogate.
188					return true
189				}
190				i += 5
191			}
192		}
193		return false
194	}
195	
196	// parseHex4 reads exactly four hexadecimal digits, either case.
197	func parseHex4(b []byte) (int, bool) {
198		v := 0
199		for _, c := range b {
200			v <<= 4
201			switch {
202			case c >= '0' && c <= '9':
203				v += int(c - '0')
204			case c >= 'a' && c <= 'f':
205				v += int(c-'a') + 10
206			case c >= 'A' && c <= 'F':
207				v += int(c-'A') + 10
208			default:
209				return 0, false
210			}
211		}
212		return v, true
213	}
214	
215	// requiredString extracts a string field that must be present, non-null and
216	// actually a JSON string.
217	func requiredString(raw map[string]json.RawMessage, name string) (string, bool) {
218		value, present := raw[name]
219		if !present || string(value) == "null" {
220			return "", false
221		}
222		var s string
223		if err := json.Unmarshal(value, &s); err != nil {
224			return "", false
225		}
226		return s, true
227	}
228	
229	// isUintLiteral reports whether the raw JSON value is a non-negative integer
230	// literal with no fraction, exponent or sign.
231	func isUintLiteral(s string) bool {
232		if s == "" {
233			return false
234		}
235		for i := 0; i < len(s); i++ {
236			if s[i] < '0' || s[i] > '9' {
237				return false
238			}
239		}
240		return true
241	}
242	
243	// normalizeOccurredAt parses a strict RFC3339 timestamp with an explicit
244	// timezone, rejects leap seconds, and returns the UTC form keeping the
245	// fractional-second digits exactly as supplied.
246	func normalizeOccurredAt(value string) (string, bool) {
247		const headLen = len("2006-01-02T15:04:05")
248		if len(value) < headLen+1 {
249			return "", false
250		}
251		head := value[:headLen]
252		if head[4] != '-' || head[7] != '-' || head[10] != 'T' || head[13] != ':' || head[16] != ':' {
253			return "", false
254		}
255		field := func(start, width int) (int, bool) {
256			v := 0
257			for i := start; i < start+width; i++ {
258				if head[i] < '0' || head[i] > '9' {
259					return 0, false
260				}
261				v = v*10 + int(head[i]-'0')
262			}
263			return v, true
264		}
265		year, ok1 := field(0, 4)
266		month, ok2 := field(5, 2)
267		day, ok3 := field(8, 2)
268		hour, ok4 := field(11, 2)
269		minute, ok5 := field(14, 2)
270		second, ok6 := field(17, 2)
271		if !ok1 || !ok2 || !ok3 || !ok4 || !ok5 || !ok6 {
272			return "", false
273		}
274		if second > 59 {
275			// Leap seconds are not accepted.
276			return "", false
277		}
278	
279		rest := value[headLen:]
280		fraction := ""
281		if strings.HasPrefix(rest, ".") {
282			i := 1
283			for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
284				i++
285			}
286			if i == 1 {
287				return "", false
288			}
289			fraction = rest[:i]
290			rest = rest[i:]
291		}
292	
293		offsetMinutes := 0
294		switch {
295		case rest == "Z":
296		case len(rest) == 6 && (rest[0] == '+' || rest[0] == '-') && rest[3] == ':' &&
297			isDigit(rest[1]) && isDigit(rest[2]) && isDigit(rest[4]) && isDigit(rest[5]):
298			oh := int(rest[1]-'0')*10 + int(rest[2]-'0')
299			om := int(rest[4]-'0')*10 + int(rest[5]-'0')
300			if oh > 23 || om > 59 {
301				return "", false
302			}
303			offsetMinutes = oh*60 + om
304			if rest[0] == '-' {
305				offsetMinutes = -offsetMinutes
306			}
307		default:
308			return "", false
309		}
310	
311		t := time.Date(year, time.Month(month), day, hour, minute, second, 0, time.UTC)
312		if t.Year() != year || int(t.Month()) != month || t.Day() != day || t.Hour() != hour || t.Minute() != minute {
313			return "", false
314		}
315		utc := t.Add(time.Duration(-offsetMinutes) * time.Minute)
316		if utc.Year() < 0 || utc.Year() > 9999 {
317			// The UTC form must stay a four-digit RFC3339 year.
318			return "", false
319		}
320		return utc.Format("2006-01-02T15:04:05") + fraction + "Z", true
321	}
322	
323	func isDigit(b byte) bool { return b >= '0' && b <= '9' }
324	
325	func writeError(c *gin.Context, status int, code, message string) {
326		c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
327	}
