462	func TestGetEventsCombinedRejectsInvalidInput(t *testing.T) {
463		router := NewRouter(openTestStore(t))
464		cases := []string{
465			"account=carol&account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z", // repeated parameter
466			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=1&limit=1",
467			"account=carol&from=2026-10-06T00:00:00Z&to=2026-10-05T00:00:00Z",           // from after to
468			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-05T00:00:00Z",           // empty window
469			"account=carol&from=2026-10-05T08:00:00%2B08:00&to=2026-10-05T00:00:00Z",    // same instant
470			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=0",   // below range
471			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=101", // above range
472			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&after_seq=-1",
473			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&after_seq=9223372036854775808",
474		}
475		for _, query := range cases {
476			wantErrorShape(t, getEventsQuery(t, router, query), http.StatusBadRequest, "invalid_audit_input")
477		}
