480	func TestGetEventsCombinedStorageUnavailable(t *testing.T) {
481		st := openTestStore(t)
482		router := NewRouter(st)
483		st.Close()
484	
485		// Even with storage down, invalid parameters are rejected as 400 first.
486		wantErrorShape(t, getEventsQuery(t, router,
487			"account=carol&account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z"),
488			http.StatusBadRequest, "invalid_audit_input")
489		wantErrorShape(t, getEventsQuery(t, router,
490			"account=carol&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=101"),
491			http.StatusBadRequest, "invalid_audit_input")
