493		// A fully valid combined request surfaces the storage failure as 503.
494		wantErrorShape(t, getEventsQuery(t, router,
495			combinedWindowQuery(combinedFrom, combinedTo, 100)+"&after_seq=10"),
496			http.StatusServiceUnavailable, "storage_unavailable")
