package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/xjeey8iust/sen-audit-ledger/internal/store"
)

// verifyResponse is the GET /ledger/verify body. FirstInvalidSeq is a pointer
// so JSON renders null when the chain is valid.
type verifyResponse struct {
	Valid           bool   `json:"valid"`
	Checked         int64  `json:"checked"`
	FirstInvalidSeq *int64 `json:"first_invalid_seq"`
}

// getLedgerVerify checks the whole ledger against the chain rules. The request
// takes no parameters: any query string is rejected before touching storage so
// an invalid request can never surface as a storage failure.
func getLedgerVerify(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		// ForceQuery catches a bare trailing "?" whose RawQuery is empty.
		if c.Request.URL.RawQuery != "" || c.Request.URL.ForceQuery {
			writeError(c, http.StatusBadRequest, "invalid_audit_input", "this endpoint does not accept query parameters")
			return
		}

		result, err := st.VerifyChain()
		if err != nil {
			writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "storage is not available")
			return
		}
		c.JSON(http.StatusOK, verifyResponse{
			Valid:           result.Valid,
			Checked:         result.Checked,
			FirstInvalidSeq: result.FirstInvalidSeq,
		})
	}
}

package api

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/xjeey8iust/sen-audit-ledger/internal/store"
)

func openTestStore(t *testing.T) *store.Store {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return st
}

func postEventBody(t *testing.T, router http.Handler, body string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodPost, "/events", strings.NewReader(body))
	router.ServeHTTP(recorder, request)
	return recorder
}

func validEventBody() string {
	return `{"account":"alice","operation":"login","resource":"console","result":"ok","occurred_at":"2026-10-05T08:30:00+08:00"}`
}

func decodeEvent(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var decoded map[string]any
	if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	return decoded
}

func wantHash(seq int64, account, operation, resource, result, occurredAt, prevHash string) string {
	// Mirror the store's escaping: backslash and double quote are escaped,
	// everything else in these test inputs stays raw.
	escape := func(s string) string {
		return strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(s)
	}
	payload := fmt.Sprintf(`[%d,"%s","%s","%s","%s","%s","%s"]`, seq,
		escape(account), escape(operation), escape(resource), escape(result), escape(occurredAt), escape(prevHash))
	sum := sha256.Sum256([]byte(payload))
	return hex.EncodeToString(sum[:])
}

