package api

import (
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/xjeey8iust/sen-audit-ledger/internal/store"
	sqlite "modernc.org/sqlite"
)

var scratchRegisterOnce sync.Once

func TestScratchCollationOverlap(t *testing.T) {
	type cmp struct{ left, right string }
	compared := make(chan cmp)
	resume := make(chan struct{})

	scratchRegisterOnce.Do(func() {
		sqlite.MustRegisterCollationUtf8("BINARY", func(left, right string) int {
			select {
			case compared <- cmp{left, right}:
				<-resume
			default:
			}
			return strings.Compare(left, right)
		})
	})

	st := openTestStore(t)
	seed := []store.EventInput{
		{Account: "alice", Operation: "op", Resource: "res", Result: "ok", OccurredAt: "2026-10-05T00:00:00Z"},
		{Account: "bob", Operation: "op", Resource: "res", Result: "ok", OccurredAt: "2026-10-05T01:00:00Z"},
		{Account: "alice", Operation: "op", Resource: "res", Result: "ok", OccurredAt: "2026-10-05T02:00:00Z"},
	}
	for _, in := range seed {
		if _, err := st.Append(in); err != nil {
			t.Fatalf("seed append: %v", err)
		}
	}

	account := "alice"
	from := "2026-10-05T00:00:00Z"
	to := "2026-10-06T00:00:00Z"
	filter := store.EventFilter{Account: &account, From: &from, To: &to, Limit: 2}

	type listResult struct {
		events []store.Event
		err    error
	}
	listed := make(chan listResult, 1)
	go func() {
		events, err := st.ListEvents(filter)
		listed <- listResult{events, err}
	}()

	// Comparison 1: seq 1 alice vs alice.
	select {
	case c := <-compared:
		t.Logf("cmp1: %q vs %q", c.left, c.right)
		resume <- struct{}{}
	case <-time.After(5 * time.Second):
		t.Fatal("timeout waiting for comparison 1")
	}
	// Comparison 2: seq 2 bob vs alice. First match fully fetched now.
	select {
	case c := <-compared:
		t.Logf("cmp2: %q vs %q", c.left, c.right)
	case <-time.After(5 * time.Second):
		t.Fatal("timeout waiting for comparison 2")
	}

	// Append while the reader is parked mid-scan.
	if _, err := st.Append(store.EventInput{Account: "alice", Operation: "op", Resource: "res", Result: "ok", OccurredAt: "2026-10-05T03:00:00Z"}); err != nil {
		t.Fatalf("overlap append: %v", err)
	}
	t.Log("append committed while reader parked")

	// Release the reader and drain remaining comparisons.
	go func() {
		for {
			select {
			case c := <-compared:
				t.Logf("cmpN: %q vs %q", c.left, c.right)
				resume <- struct{}{}
			case <-time.After(2 * time.Second):
				return
			}
		}
	}()
	resume <- struct{}{}

	var result listResult
	select {
	case result = <-listed:
	case <-time.After(5 * time.Second):
		t.Fatal("timeout waiting for ListEvents")
	}
	if result.err != nil {
		t.Fatalf("ListEvents: %v", result.err)
	}
	for _, e := range result.events {
		t.Logf("event seq=%d account=%q", e.Seq, e.Account)
	}
	if len(result.events) != 2 || result.events[0].Seq != 1 || result.events[1].Seq != 3 {
		t.Fatalf("events = %v, want seqs 1 and 3", result.events)
	}
}

